/**
 * Advanced DOM Selector Generation Engine
 * Prioritizes stable, semantic, and maintainable selectors while avoiding dynamic IDs,
 * Tailwind/utility classes, and deep positional chains.
 */

import { SelectorCandidate, SelectorStrategy } from './types';

/**
 * Checks if an ID appears to be dynamic, generated by a framework or random hashing.
 */
export function isDynamicId(id: string): boolean {
  if (!id || typeof id !== 'string') return true;
  const trimmed = id.trim();
  if (trimmed.length === 0) return true;

  // Leading digits are invalid in standard CSS ID selectors and often dynamic
  if (/^[0-9]/.test(trimmed)) return true;

  // Framework colon or special character patterns (e.g. :r1:, /123/, \a\)
  if (/[:/\\#.[\]]/.test(trimmed)) return true;

  // Well-known frontend framework auto-generated ID patterns
  if (
    /(ember|react|vue|ng|guid|gen|uid|item|select|radix|headlessui|chakra|next|sc|css|jss|styled)-?[a-z0-9_-]+/i.test(
      trimmed
    )
  ) {
    return true;
  }

  // Pure numeric IDs
  if (/^\d+$/.test(trimmed)) return true;

  // Hexadecimal or hash-like strings (e.g. 8+ hex digits)
  if (/^[a-f0-9]{8,}$/i.test(trimmed)) return true;

  // Base64-like or random alphanumeric sequences of 10+ characters with mixed case
  if (trimmed.length >= 10 && /[A-Z]/.test(trimmed) && /[a-z]/.test(trimmed) && /[0-9]/.test(trimmed)) {
    return true;
  }

  return false;
}

/**
 * Detects utility, presentation-only, and state classes (e.g. Tailwind, Bootstrap, CSS modules, state tags)
 */
export function isPresentationOrUtilityClass(cls: string): boolean {
  if (!cls || typeof cls !== 'string') return true;
  const c = cls.trim();
  if (c.length === 0) return true;

  // Skip state classes that change on user interaction
  if (
    /^(active|hover|focus|selected|open|closed|is-open|is-active|is-selected|is-disabled|is-loading|visible|hidden|disabled|loading|expanded|collapsed)$/i.test(
      c
    )
  ) {
    return true;
  }

  // Tailwind arbitrary value classes or variants with colons/brackets
  if (c.includes(':') || c.includes('[') || c.includes(']')) {
    return true;
  }

  // Common CSS-in-JS and CSS module hashed suffixes (e.g. css-14x9ab, sc-bdVaJa, jss123, App_header__3xL2)
  if (/^(css|sc|jss|styled)-[a-zA-Z0-9]+$/i.test(c)) return true;
  if (/_[a-zA-Z0-9]{5,}$/.test(c)) return true;

  // Layout & display utility classes
  if (/^(flex|inline-flex|grid|inline-grid|block|inline-block|inline|contents|hidden)$/i.test(c)) {
    return true;
  }

  // Flexbox & Grid alignment & direction
  if (
    /^(items|justify|content|self|place)-(start|end|center|between|around|evenly|stretch|baseline)/i.test(
      c
    )
  ) {
    return true;
  }
  if (/^(flex-(row|col|row-reverse|col-reverse|wrap|nowrap)|grow|shrink|basis-\w+)$/i.test(c)) {
    return true;
  }
  if (/^(grid-cols-\d+|col-span-\d+|grid-rows-\d+|row-span-\d+|gap(-\w+)?-\d+)$/i.test(c)) {
    return true;
  }

  // Spacing utilities (margin, padding)
  if (/^[-+]?[pm][trblxy]?(-\w+)?-\d+$/i.test(c)) return true;

  // Sizing utilities (width, height, max-w, min-h, etc.)
  if (/^(w|h|min-w|min-h|max-w|max-h)(-\w+)?-\w+$/i.test(c)) return true;

  // Typography utilities (font-size, font-weight, text-align, text-color)
  if (/^text-(xs|sm|base|lg|xl|\d+xl|left|center|right|justify)$/i.test(c)) return true;
  if (/^font-(thin|extralight|light|normal|medium|semibold|bold|extrabold|black)$/i.test(c)) {
    return true;
  }
  if (/^leading-(none|tight|snug|normal|relaxed|loose|\d+)$/i.test(c)) return true;

  // Borders, colors, shadows, rounded
  if (/^(rounded|border|shadow)(-\w+)?$/i.test(c)) return true;
  if (/^(bg|text|border|fill|stroke)-([a-z]+-\d+|white|black|transparent|current)$/i.test(c)) {
    return true;
  }

  // Positioning
  if (/^(relative|absolute|fixed|sticky|static|top-\d+|bottom-\d+|left-\d+|right-\d+|z-\d+)$/i.test(c)) {
    return true;
  }

  return false;
}

/**
 * Filters a class list to retain only meaningful semantic classes.
 */
export function filterSemanticClasses(classList: DOMTokenList | string[]): string[] {
  const list = Array.isArray(classList) ? classList : Array.from(classList);
  return list.filter((cls) => !isPresentationOrUtilityClass(cls));
}

/**
 * Escapes special CSS selector characters safely.
 */
export function escapeCssSelector(value: string): string {
  if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
    return CSS.escape(value);
  }
  return value.replace(/([!"#$%&'()*+,./:;<=>?@[\\\]^`{|}~])/g, '\\$1');
}

/**
 * Safely counts matching elements for a selector within root.
 */
function queryMatchCount(selector: string, root: Document | Element = document): number {
  if (!selector) return 0;
  try {
    return root.querySelectorAll(selector).length;
  } catch {
    return 0;
  }
}

/**
 * Calculates specificity score for ranking selectors.
 */
function calculateSpecificity(selector: string): number {
  let score = 0;
  // ID selectors: weight 100
  const ids = (selector.match(/#[a-zA-Z0-9_-]+/g) || []).length;
  score += ids * 100;

  // Attribute and class selectors: weight 10
  const attrs = (selector.match(/\[[^\]]+\]/g) || []).length;
  const classes = (selector.match(/\.[a-zA-Z0-9_-]+/g) || []).length;
  score += (attrs + classes) * 10;

  // Tag selectors: weight 1
  const tags = (selector.match(/^[a-zA-Z0-9_-]+|[\s>+~][a-zA-Z0-9_-]+/g) || []).length;
  score += tags * 1;

  // Penalty for :nth-child (positional fragility)
  const nth = (selector.match(/:nth-child/g) || []).length;
  score -= nth * 25;

  return Math.max(1, score);
}

/**
 * Generates an attribute selector for an element if stable attributes exist.
 */
function getStableAttributeSelector(element: Element): { selector: string; strategy: SelectorStrategy } | null {
  // 1. Test attributes (highest priority)
  const testAttributes = [
    'data-testid',
    'data-test-id',
    'data-test',
    'data-qa',
    'data-cy',
    'data-component',
    'data-automation-id'
  ];

  for (const attr of testAttributes) {
    const val = element.getAttribute(attr);
    if (val && !isDynamicId(val)) {
      return {
        selector: `[${attr}="${escapeCssSelector(val)}"]`,
        strategy: 'test-attribute'
      };
    }
  }

  // 2. Functional & Semantic attributes
  const tagName = element.tagName.toLowerCase();

  // Name attribute for form controls
  const nameVal = element.getAttribute('name');
  if (nameVal && !isDynamicId(nameVal)) {
    const sel = `${tagName}[name="${escapeCssSelector(nameVal)}"]`;
    return { selector: sel, strategy: 'semantic-attribute' };
  }

  // Aria-label for interactive/accessible elements
  const ariaLabel = element.getAttribute('aria-label');
  if (ariaLabel && ariaLabel.length > 2 && ariaLabel.length < 50 && !isDynamicId(ariaLabel)) {
    const sel = `${tagName}[aria-label="${escapeCssSelector(ariaLabel)}"]`;
    return { selector: sel, strategy: 'semantic-attribute' };
  }

  // Alt for images
  if (tagName === 'img') {
    const alt = element.getAttribute('alt');
    if (alt && alt.trim().length > 2 && alt.length < 50) {
      const sel = `img[alt="${escapeCssSelector(alt.trim())}"]`;
      return { selector: sel, strategy: 'semantic-attribute' };
    }
  }

  // Stable data-* attributes
  for (let i = 0; i < element.attributes.length; i++) {
    const a = element.attributes[i];
    if (
      a.name.startsWith('data-') &&
      !testAttributes.includes(a.name) &&
      a.value &&
      !isDynamicId(a.value) &&
      a.value.length < 50
    ) {
      return {
        selector: `[${a.name}="${escapeCssSelector(a.value)}"]`,
        strategy: 'semantic-attribute'
      };
    }
  }

  return null;
}

/**
 * Builds a clean scoped hierarchy selector by ascending to the nearest stable parent anchor.
 */
function buildScopedHierarchySelector(element: Element, root: Document | Element = document): string {
  const parts: string[] = [];
  let curr: Element | null = element;

  while (curr && curr !== root && curr !== document.body && curr !== document.documentElement) {
    let part = curr.tagName.toLowerCase();

    // Check stable attribute on current
    const attrSel = getStableAttributeSelector(curr);
    if (attrSel && queryMatchCount(attrSel.selector, root) === 1) {
      parts.unshift(attrSel.selector);
      break;
    }

    // Check stable ID on current
    if (curr.id && !isDynamicId(curr.id)) {
      part = `#${escapeCssSelector(curr.id)}`;
      parts.unshift(part);
      break;
    }

    // Check semantic classes
    const classes = filterSemanticClasses(curr.classList);
    if (classes.length > 0) {
      part += `.${classes.slice(0, 2).map(escapeCssSelector).join('.')}`;
    }

    // Disambiguate against siblings if needed
    const parent = curr.parentElement;
    if (parent) {
      const siblingsWithSameTag = Array.from(parent.children).filter((c) => {
        try {
          return c.matches(part);
        } catch {
          return c.tagName === curr?.tagName;
        }
      });

      if (siblingsWithSameTag.length > 1) {
        const index = Array.from(parent.children).indexOf(curr) + 1;
        part += `:nth-child(${index})`;
      }
    }

    parts.unshift(part);

    // Stop if the accumulated selector is already unique
    const currentCombined = parts.join(' > ');
    if (queryMatchCount(currentCombined, root) === 1) {
      return currentCombined;
    }

    curr = curr.parentElement;
  }

  return parts.join(' > ');
}

/**
 * Generates an array of evaluated selector candidates for an element.
 */
export function generateSelectorCandidates(
  element: Element,
  root: Document | Element = document
): SelectorCandidate[] {
  if (!(element instanceof Element)) return [];

  const candidatesMap = new Map<string, SelectorCandidate>();

  function registerCandidate(selector: string, strategy: SelectorStrategy, baseConfidence: number) {
    if (!selector || candidatesMap.has(selector)) return;
    const matchCount = queryMatchCount(selector, root);
    if (matchCount === 0) return;

    const isUnique = matchCount === 1;
    const specificity = calculateSpecificity(selector);

    // Adjust confidence based on uniqueness and specificity
    let confidence = baseConfidence;
    if (!isUnique) confidence *= 0.5;
    if (selector.includes(':nth-child')) confidence *= 0.8;
    if (selector.split('>').length > 4) confidence *= 0.85;

    candidatesMap.set(selector, {
      selector,
      strategy,
      specificity,
      isUnique,
      matchCount,
      confidence: Math.round(confidence * 100) / 100
    });
  }

  // 1. Stable Test / Data Attributes
  const attrCandidate = getStableAttributeSelector(element);
  if (attrCandidate) {
    registerCandidate(attrCandidate.selector, attrCandidate.strategy, 0.98);
  }

  // 2. Stable ID
  if (element.id && !isDynamicId(element.id)) {
    const idSel = `#${escapeCssSelector(element.id)}`;
    registerCandidate(idSel, 'id', 0.95);
  }

  // 3. Semantic Classes
  const tagName = element.tagName.toLowerCase();
  const semanticClasses = filterSemanticClasses(element.classList);

  if (semanticClasses.length > 0) {
    // Single distinctive semantic class
    for (const cls of semanticClasses) {
      registerCandidate(`.${escapeCssSelector(cls)}`, 'semantic-class', 0.85);
      registerCandidate(`${tagName}.${escapeCssSelector(cls)}`, 'semantic-class', 0.88);
    }

    // Combination of semantic classes
    if (semanticClasses.length > 1) {
      const combined = `${tagName}.${semanticClasses.slice(0, 2).map(escapeCssSelector).join('.')}`;
      registerCandidate(combined, 'semantic-class', 0.9);
    }
  }

  // 4. Semantic Element by Tag Name
  const semanticTags = ['header', 'footer', 'nav', 'main', 'article', 'section', 'aside', 'h1', 'h2', 'h3', 'table', 'form'];
  if (semanticTags.includes(tagName)) {
    registerCandidate(tagName, 'semantic-attribute', 0.7);
  }

  // 5. Scoped Parent-Child Hierarchy
  const hierarchySel = buildScopedHierarchySelector(element, root);
  if (hierarchySel) {
    registerCandidate(hierarchySel, 'hierarchy', 0.82);
  }

  // Convert to sorted array (unique matches first, higher confidence first)
  const candidates = Array.from(candidatesMap.values()).sort((a, b) => {
    if (a.isUnique !== b.isUnique) {
      return a.isUnique ? -1 : 1;
    }
    return b.confidence - a.confidence;
  });

  return candidates;
}

/**
 * Returns the best stable selector for the given element.
 */
export function generateBestSelector(element: Element, root: Document | Element = document): string {
  const candidates = generateSelectorCandidates(element, root);

  // Return the first unique candidate with highest confidence
  const uniqueCandidate = candidates.find((c) => c.isUnique);
  if (uniqueCandidate) {
    return uniqueCandidate.selector;
  }

  // Fallback: if no single unique candidate, return top candidate or scoped hierarchy
  if (candidates.length > 0) {
    return candidates[0].selector;
  }

  return buildScopedHierarchySelector(element, root);
}

/**
 * Generates a minimal relative selector for a target element relative to its container.
 */
export function generateRelativeSelector(container: Element, target: Element): string {
  if (container === target) return '';

  // Direct class match
  const classes = filterSemanticClasses(target.classList);
  const tagName = target.tagName.toLowerCase();

  for (const cls of classes) {
    const candidate = `.${escapeCssSelector(cls)}`;
    try {
      if (container.querySelectorAll(candidate).length === 1) {
        return candidate;
      }
    } catch {
      // Continue
    }
  }

  // Tag match if unique inside container (e.g. h2, img, a, price)
  try {
    if (container.querySelectorAll(tagName).length === 1) {
      return tagName;
    }
  } catch {
    // Continue
  }

  // Stable attribute inside container
  const attrCandidate = getStableAttributeSelector(target);
  if (attrCandidate) {
    try {
      if (container.querySelectorAll(attrCandidate.selector).length === 1) {
        return attrCandidate.selector;
      }
    } catch {
      // Continue
    }
  }

  // Ascend from target up to container
  const segments: string[] = [];
  let current: Element | null = target;

  while (current && current !== container && current.parentElement) {
    let part = current.tagName.toLowerCase();
    const semClasses = filterSemanticClasses(current.classList);
    if (semClasses.length > 0) {
      part += `.${escapeCssSelector(semClasses[0])}`;
    }

    const parent = current.parentElement;
    const matchingSiblings = Array.from(parent.children).filter((c) => {
      try {
        return c.matches(part);
      } catch {
        return c.tagName === current?.tagName;
      }
    });

    if (matchingSiblings.length > 1) {
      const index = Array.from(parent.children).indexOf(current) + 1;
      part += `:nth-child(${index})`;
    }

    segments.unshift(part);
    current = current.parentElement;
  }

  return segments.join(' > ');
}

/**
 * Generates an XPath expression for an element.
 */
export function generateXPath(element: Element): string {
  if (!(element instanceof Element)) return '';

  if (element.id && !isDynamicId(element.id)) {
    return `//*[@id="${element.id}"]`;
  }

  const paths: string[] = [];
  let current: Element | null = element;

  while (current && current.nodeType === Node.ELEMENT_NODE && current !== document.body && current !== document.documentElement) {
    let index = 1;
    let sibling = current.previousElementSibling;

    while (sibling) {
      if (sibling.tagName === current.tagName) {
        index++;
      }
      sibling = sibling.previousElementSibling;
    }

    const tagName = current.tagName.toLowerCase();
    const pathSegment = index > 1 ? `${tagName}[${index}]` : tagName;
    paths.unshift(pathSegment);
    current = current.parentElement;
  }

  return `//${paths.join('/')}`;
}
